function solve(a,b){const c=[...a].sort((a,b)=>a-b);const r=[];const d=c.length;for(let i=0;i<d-3;i++){if(i>0&&c[i]===c[i-1]){continue;}const a=c[i]+c[i+1]+c[i+2]+c[i+3];if(a>b){break;}const e=c[i]+c[d-3]+c[d-2]+c[d-1];if(e<b){continue;}for(let j=i+1;j<d-2;j++){if(j>i+1&&c[j]===c[j-1]){continue;}const a=c[i]+c[j]+c[j+1]+c[j+2];if(a>b){break;}const e=c[i]+c[j]+c[d-2]+c[d-1];if(e<b){continue;}let f=j+1;let g=d-1;while(f<g){const a=c[i]+c[j]+c[f]+c[g];if(a<b){f++;}else if(a>b){g--;}else{r.push([c[i],c[j],c[f],c[g]]);f++;g--;while(f<g&&c[f]===c[f-1]){f++;}while(f<g&&c[g]===c[g+1]){g--;}}}}}return r;}
